Lemma sub_tail2 (hi lw e' : Z) :
  (2 ^ 51 <= hi < 2 ^ 52)%Z -> (0 <= lw < 2 ^ 64)%Z -> (lw mod 8 = 0)%Z -> (1 <= e' <= 32766)%Z ->
  evt rsegs (fun ms' => exists t0' t1' t2' a2' a3' a4' a5' a6' a7',
      ms' = MS (mkR ora sp gp tp t0' t1' t2' os0 os1 (Z_to_bv 64 (lw / 8 + (hi mod 8) * 2 ^ 61)) (Z_to_bv 64 (e' * 2 ^ 48 + (hi / 8 - 2 ^ 48)))
                    a2' a3' a4' a5' a6' a7' os2 os3 os4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (ret_pc ora) fc None m (seg_rom rsegs))
    (MS (mkR ra0 (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2 q8 q9
             (Z_to_bv 64 hi) (Z_to_bv 64 lw) (Z_to_bv 64 (-1)) (Z_to_bv 64 281474976710655) a4 (Z_to_bv 64 e') a6 a7
