Hypothesis MI : mem_inv rsegs m.

Lemma sub_tail1 (x f Dhi Dlo e ahi : Z) :
  (0 < x < 2 ^ 64)%Z -> (0 <= f <= 1)%Z -> (0 <= Dhi < 2 ^ 64)%Z -> (0 <= Dlo < 2 ^ 64)%Z -> (0 <= ahi < 2 ^ 63)%Z ->
  (113 <= e <= 32766)%Z -> (13 <= 63 - Z.log2 x + 64 * f <= 75)%Z ->
  let sh := (51 - Z.log2 x + f * 64)%Z in
  let hi := ((Dhi mod 2 ^ (64 - sh)) * 2 ^ sh + Dlo / 2 ^ (64 - sh))%Z in
  let lw := ((Dlo * 2 ^ sh) mod 2 ^ 64)%Z in
  (2 ^ 51 <= hi < 2 ^ 52)%Z -> (lw mod 8 = 0)%Z ->
  evt rsegs (fun ms' => exists t0' t1' t2' a2' a3' a4' a5' a6' a7' t3',
      ms' = MS (mkR ora sp gp tp t0' t1' t2' os0 os1 (Z_to_bv 64 (lw / 8 + (hi mod 8) * 2 ^ 61)) (Z_to_bv 64 ((e - sh) * 2 ^ 48 + (hi / 8 - 2 ^ 48)))
                    a2' a3' a4' a5' a6' a7' os2 os3 os4 s5 s6 s7 s8 s9 s10 s11 t3' t4 t5 t6) F (ret_pc ora) fc None m (seg_rom rsegs))
    (MS (mkR ra0 (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2 q8 q9
             (Z_to_bv 64 Dhi) (Z_to_bv 64 Dlo) (Z_to_bv 64 (-1)) (Z_to_bv 64 281474976710655) (Z_to_bv 64 ahi) (Z_to_bv 64 e) (Z_to_bv 64 f) (Z_to_bv 64 x)
             q18 q19 q20 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (Z_to_bv 64 0xb2a28) fc None m (seg_rom rsegs)).
