Definition sub_pro_post (sp gp tp t2 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 ra s0 s1 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo : Z) (m : word -> option byte) (e ha la hb lb : Z) : machine_state -> Prop :=
  fun ms' => exists m1,
    ms' = MS (mkR ra (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp (Z_to_bv 64 e) (Z_to_bv 64 hb) t2
                  (Z_to_bv 64 (e * 281474976710656 + hb + 9223372036854775808)) (Z_to_bv 64 lb)
                  (Z_to_bv 64 la) (Z_to_bv 64 (e * 281474976710656 + ha)) (Z_to_bv 64 (-1)) (Z_to_bv 64 281474976710655)
                  (Z_to_bv 64 (e * 281474976710656 + ha)) (Z_to_bv 64 e) (Z_to_bv 64 lb) (Z_to_bv 64 ha)
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (Z_to_bv 64 0xb2960) fc None m1 (seg_rom rsegs)
    /\ munch [(bv_unsigned sp + -48, bv_unsigned sp)]%Z m m1 /\ wmono rsegs m m1 /\ mem_inv rsegs m1
    /\ stk rsegs m1 lo (bv_unsigned sp + -48)
    /\ rw_cells rsegs m1 (bv_unsigned sp + -48) [C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

