Lemma sub_pro : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (lo : Z) (e ha la hb lb : Z),
  stk rsegs m lo (bv_unsigned sp) -> mem_inv rsegs m -> (lo <= bv_unsigned sp - 48)%Z ->
  (1 <= e <= 32766)%Z -> (0 <= ha < 2 ^ 48)%Z -> (0 <= la < 2 ^ 64)%Z -> (0 <= hb < 2 ^ 48)%Z -> (0 <= lb < 2 ^ 64)%Z ->
  (hb < ha \/ (hb = ha /\ lb <= la))%Z ->
  a0 = Z_to_bv 64 la -> a1 = Z_to_bv 64 (e * 2 ^ 48 + ha) -> a2 = Z_to_bv 64 lb -> a3 = Z_to_bv 64 (e * 2 ^ 48 + hb) ->
  evt rsegs (sub_pro_post sp gp tp t2 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 ra s0 s1 F fc lo m e ha la hb lb)
