Lemma borrow_sub AH AL BH BL : 0 <= AH < 2 ^ 64 -> 0 <= AL < 2 ^ 64 -> 0 <= BH < 2 ^ 64 -> 0 <= BL < 2 ^ 64 ->
  BH * 2 ^ 64 + BL < AH * 2 ^ 64 + AL ->
  (AH - BH - Z.b2z (AL <? BL)) * 2 ^ 64 + (AL - BL) mod 2 ^ 64 = (AH * 2 ^ 64 + AL) - (BH * 2 ^ 64 + BL)
  /\ 0 <= AH - BH - Z.b2z (AL <? BL).
Proof.
