(* [comment removed for export] *)
Lemma sub_main (e ha la hb lb : Z) :
  (113 <= e <= 32766)%Z -> (0 <= ha < 2 ^ 48)%Z -> (0 <= la < 2 ^ 64)%Z -> (0 <= hb < 2 ^ 48)%Z -> (0 <= lb < 2 ^ 64)%Z ->
  (hb < ha \/ (hb = ha /\ lb < la))%Z ->
  let N := ((ha - hb) * 2 ^ 64 + (la - lb))%Z in (2 ^ 49 <= N)%Z ->
  evt rsegs (fun ms' => exists t0' t1' t2' a2' a3' a4' a5' a6' a7' t3' t4' t5',
      ms' = MS (mkR ora sp gp tp t0' t1' t2' os0 os1 (Z_to_bv 64 (qS N mod 2 ^ 64)) (Z_to_bv 64 ((e - 112 + Z.log2 N) * 2 ^ 48 + (qS N / 2 ^ 64 - 2 ^ 48)))
                    a2' a3' a4' a5' a6' a7' os2 os3 os4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6) F (ret_pc ora) fc None m (seg_rom rsegs))
   (MS (mkR ra0 (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp (Z_to_bv 64 e) (Z_to_bv 64 hb) t2
                  (Z_to_bv 64 (e * 281474976710656 + hb + 9223372036854775808)) (Z_to_bv 64 lb)
                  (Z_to_bv 64 la) (Z_to_bv 64 (e * 281474976710656 + ha)) (Z_to_bv 64 (-1)) (Z_to_bv 64 281474976710655)
                  (Z_to_bv 64 (e * 281474976710656 + ha)) (Z_to_bv 64 e) (Z_to_bv 64 lb) (Z_to_bv 64 ha)
                  q18 q19 q20 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (Z_to_bv 64 0xb2960) fc None m (seg_rom rsegs)).
Proof.
