(* [comment removed for export] *)
Theorem sub_walk_self : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (lo : Z) (Na Ea : Z),
  stk rsegs m lo (bv_unsigned sp) -> mem_inv rsegs m -> (lo <= bv_unsigned sp - 48)%Z ->
  qok Na Ea -> (113 <= qB Na Ea)%Z ->
  bv_unsigned a0 = lo64 (qenc Na Ea) -> bv_unsigned a1 = hi64 (qenc Na Ea) ->
  bv_unsigned a2 = lo64 (qenc Na Ea) -> bv_unsigned a3 = hi64 (qenc Na Ea) ->
  evt rsegs (sub_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc lo m 0 0)
