Hypothesis FR : rw_cells rsegs m (bv_unsigned sp + -48) [C8 os4; C8 os3; C8 os2; C8 os1; C8 os0; C8 ora].
Hypothesis ST : stk rsegs m lo (bv_unsigned sp + -48).
Hypothesis MI : mem_inv rsegs m.

Definition body_post : machine_state -> Prop := fun ms' => exists t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' (fc' : bv 32),
  ms' = MS (mkR ora sp gp tp t0' t1' t2' os0 os1 a0' a1' a2' a3' a4' a5' a6' a7' os2 os3 os4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6') F (ret_pc ora) fc' None m (seg_rom rsegs).
Ltac vf_leaf_b2d48 := leaf getround_walk by (try exact MI).
Ltac vf_leaf_b2d78 := leaf raise_inexact_walk by (try exact MI).
Ltac vf_fin := idtac; lazymatch goal with |- evt _ _ (MS _ _ (ret_pc _) _ _ _ _) => apply evt_done; unfold body_post; do 16 eexists; reflexivity end.

