(* [comment removed for export] *)
Definition miter_W (sp : word) (B i k : Z) : list (Z * Z) :=
  [(bv_unsigned sp + -80, bv_unsigned sp); (B + 4 * i, B + 4 * i + 4 * k)]%Z.

Definition miter_post (sp gp tp s0 s2 s3 s4 s6 s10 : word) (F : bvmap 5 word) (fc : bv 32) (lo : Z) (m : word -> option byte)
    (B i : Z) (ws : list word) (n y' : Z) : machine_state -> Prop :=
  fun ms' => exists t0' t1' t2' s1' a0' a1' a2' a3' a4' a5' a6' a7' s5' t3' t4' t5' t6' m',
    ms' = MS (mkR (Z_to_bv 64 0xb0754) sp gp tp t0' t1' t2' s0 s1' a0' a1' a2' a3' a4' a5' a6' a7'
                  s2 s3 s4 s5' s6 (Z_to_bv 64 (B + 4 * i + 4)) (Z_to_bv 64 (lo64 y')) (Z_to_bv 64 (hi64 y')) s10 (Z_to_bv 64 n)
                  t3' t4' t5' t6') F (Z_to_bv 64 (if (y' =? 0)%Z then 0xb0758 else 0xb06e8)) fc None m' (seg_rom rsegs)
    /\ munch (miter_W sp B i 1) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp) /\ u32arr rsegs m' B (upd ws (Z.to_nat i) (Z_to_bv 64 n)).

(* [comment removed for export] *)
Lemma miter_walk : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (lo : Z) (B i M : Z) (ws : list word),
  stk rsegs m lo (bv_unsigned sp) -> mem_inv rsegs m -> (lo <= bv_unsigned sp - 80)%Z ->
  u32arr rsegs m B ws -> (bv_unsigned sp <= B)%Z -> (0 <= i < Z.of_nat (length ws))%Z ->
  (0 < M < 2 ^ 54)%Z ->
  s7 = Z_to_bv 64 (B + 4 * i) -> bv_unsigned s8 = lo64 (qenc M (-24)) -> bv_unsigned s9 = hi64 (qenc M (-24)) ->
  s10 = Z_to_bv 64 1000000000 ->
  evt rsegs (miter_post sp gp tp s0 s2 s3 s4 s6 s10 F fc lo m B i ws (M / 2 ^ 24)
               (if (M mod 2 ^ 24 =? 0)%Z then 0%Z else qenc (mnext M) (-24)))
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (Z_to_bv 64 0xb06e8) fc None m (seg_rom rsegs)).
Proof.
