Ltac vf_go step fin := repeat (first [ lazymatch goal with |- evt _ _ (MS _ _ (Z_to_bv 64 ?pc) _ _ _ _) => is_Zlit pc; step pc end
                                      | vf_br | fin ]).

Section Body.
Variables (ra sp gp tp t0 t1 t2 s0 s1 a0 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (m : word -> option byte) (lo : Z).
Hypothesis MI : mem_inv rsegs m.

Definition body_post : machine_state -> Prop := fun ms' => exists a1' a2' a3' (fc' : bv 32),
  ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1' a2' a3' a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (ret_pc ra) fc' None m (seg_rom rsegs).
Ltac vf_fin := idtac; lazymatch goal with |- evt _ _ (MS _ _ (ret_pc _) _ _ _ _) => apply evt_done; unfold body_post; do 4 eexists; reflexivity end.

Lemma blk_b69ec : forall (a1 a2 a3 : word) (fc : bv 32),
  evt rsegs body_post (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (Z_to_bv 64 0xb6a28) fc None m (seg_rom rsegs)).
